// TranscriptMeasurement records transcript footprint, token estimation, and compaction statistics (§4.4.1).
type TranscriptMeasurement struct {
	BaseRecord
	TranscriptID              string  `json:"transcript_id,omitempty"`
	Source                    string  `json:"source,omitempty"` // "monolithic_full", "chunked_full", "compact"
	IsSubagent                bool    `json:"is_subagent"`
	StepCount                 int     `json:"step_count"`
	RawBytes                  int64   `json:"raw_bytes"`
	RawChars                  int64   `json:"raw_chars"`
	EstimatedTokens           int64   `json:"estimated_tokens"`
	ToolTrafficBytes          int64   `json:"tool_traffic_bytes"`
	ToolTrafficChars          int64   `json:"tool_traffic_chars"`
	ToolTrafficTokens         int64   `json:"tool_traffic_tokens"`
	ToolTrafficPct            float64 `json:"tool_traffic_pct"`
	CompactedChars            int64   `json:"compacted_chars,omitempty"`
	CompactedTokens           int64   `json:"compacted_tokens,omitempty"`
	CompactionRatio           float64 `json:"compaction_ratio,omitempty"`
	TruncationExpansionRatio  float64 `json:"truncation_expansion_ratio,omitempty"` // full bytes / compact bytes
}

// GenericRecord is a fallback record for unmarshaling arbitrary JSONL metrics.
type GenericRecord struct {
	BaseRecord
	Data map[string]any `json:"-"`
}

// UnmarshalJSON unmarshals BaseRecord and preserves remaining fields in Data.
func (g *GenericRecord) UnmarshalJSON(b []byte) error {
	type Alias BaseRecord
	var base Alias
	if err := json.Unmarshal(b, &base); err != nil {
		return err
	}
	g.BaseRecord = BaseRecord(base)
	var raw map[string]any
	if err := json.Unmarshal(b, &raw); err != nil {
		return err
	}
	delete(raw, "timestamp")
	delete(raw, "type")
	delete(raw, "repo_id")
	delete(raw, "session_id")
	g.Data = raw
	return nil
}

package metrics

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
)

// ErrClosed is returned when writing to a closed Writer.
var ErrClosed = errors.New("metrics writer is closed")

// WriterOption configures a metrics Writer.
type WriterOption func(*writerConfig)

type writerConfig struct {
	fileName    string
	syncOnWrite bool
	customIO    io.Writer
}

// WithFileName sets a fixed file name rather than daily rotation (e.g., "metrics.jsonl").
func WithFileName(name string) WriterOption {
	return func(c *writerConfig) {
		c.fileName = name
	}
}

// WithSyncOnWrite enables flushing and syncing to disk on every write.
func WithSyncOnWrite(sync bool) WriterOption {
	return func(c *writerConfig) {
		c.syncOnWrite = sync
	}
}

// WithCustomWriter configures writing to an arbitrary io.Writer.
func WithCustomWriter(w io.Writer) WriterOption {
	return func(c *writerConfig) {
		c.customIO = w
	}
}

// Writer handles thread-safe appending of JSONL metrics records.
// In filesystem mode, records are persisted under <data-dir>/<repo-id>/metrics/*.jsonl (SPEC §10.4).
type Writer struct {
	mu          sync.Mutex
	dataDir     string
	repoID      string
	dirPath     string
	fixedFile   string
	syncOnWrite bool
	customIO    io.Writer

	currentFile *os.File
	currentDate string
	closed      bool
}

// NewWriter creates a new JSONL metrics writer for the specified repository.
func NewWriter(dataDir, repoID string, opts ...WriterOption) (*Writer, error) {
	if dataDir == "" {
		dataDir = config.DataDir()
	}
	if repoID == "" {
		return nil, errors.New("repoID cannot be empty")
	}

	cfg := writerConfig{}
	for _, opt := range opts {
		opt(&cfg)
	}

	metricsDir := filepath.Join(dataDir, repoID, "metrics")
	if cfg.customIO == nil {
		if err := os.MkdirAll(metricsDir, 0700); err != nil {
			return nil, fmt.Errorf("creating metrics directory %s: %w", metricsDir, err)
		}
	}

	return &Writer{
		dataDir:     dataDir,
		repoID:      repoID,
		dirPath:     metricsDir,
		fixedFile:   cfg.fileName,
		syncOnWrite: cfg.syncOnWrite,
		customIO:    cfg.customIO,
	}, nil
}

// NewWriterFromIO creates a metrics writer backed by an arbitrary io.Writer (e.g. for testing or piping).
func NewWriterFromIO(w io.Writer) *Writer {
	return &Writer{
		customIO: w,
	}
}

// Write marshals and appends a single Record as a JSONL line.
func (w *Writer) Write(record Record) error {
	return w.WriteAny(record)
}

// WriteAny marshals and appends any metric struct or map as a JSON line.
func (w *Writer) WriteAny(v any) error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.closed {
		return ErrClosed
	}

	data, err := json.Marshal(v)
	if err != nil {
		return fmt.Errorf("marshaling metrics record: %w", err)
	}
	data = append(data, '\n')

	if w.customIO != nil {
		_, err := w.customIO.Write(data)
		return err
	}

	dest, err := w.ensureFileLocked(time.Now().UTC())
	if err != nil {
		return err
	}

	if _, err := dest.Write(data); err != nil {
		return fmt.Errorf("writing metrics JSONL: %w", err)
	}

	if w.syncOnWrite {
		if err := dest.Sync(); err != nil {
			return fmt.Errorf("syncing metrics file: %w", err)
		}
	}

	return nil
}

// WriteCaptureHealth writes a CaptureHealth record.
func (w *Writer) WriteCaptureHealth(m CaptureHealth) error {
	if m.Type == "" {
		m.Type = MetricTypeCaptureHealth
	}
	if m.Timestamp.IsZero() {
		m.Timestamp = time.Now().UTC()
	}
	if m.RepoID == "" {
		m.RepoID = w.repoID
	}
	return w.Write(m)
}

// WriteHookExecution writes a HookExecution record.
func (w *Writer) WriteHookExecution(m HookExecution) error {
	if m.Type == "" {
		m.Type = MetricTypeHookExecution
	}
	if m.Timestamp.IsZero() {
		m.Timestamp = time.Now().UTC()
	}
	if m.RepoID == "" {
		m.RepoID = w.repoID
	}
	return w.Write(m)
}

// WriteTickHealth writes a TickHealth record.
func (w *Writer) WriteTickHealth(m TickHealth) error {
	if m.Type == "" {
		m.Type = MetricTypeTickHealth
	}
	if m.Timestamp.IsZero() {
		m.Timestamp = time.Now().UTC()
	}
	if m.RepoID == "" {
		m.RepoID = w.repoID
	}
	return w.Write(m)
}

// WriteBudgetExhaustion writes a BudgetExhaustion record.
func (w *Writer) WriteBudgetExhaustion(m BudgetExhaustion) error {
	if m.Type == "" {
		m.Type = MetricTypeBudgetExhaustion
	}
	if m.Timestamp.IsZero() {
		m.Timestamp = time.Now().UTC()
	}
	if m.RepoID == "" {
		m.RepoID = w.repoID
	}
	return w.Write(m)
}

// WriteTranscriptMeasurement writes a TranscriptMeasurement record.
func (w *Writer) WriteTranscriptMeasurement(m TranscriptMeasurement) error {
	if m.Type == "" {
		m.Type = MetricTypeTranscriptMeasurement
	}
	if m.Timestamp.IsZero() {
		m.Timestamp = time.Now().UTC()
	}
	if m.RepoID == "" {
		m.RepoID = w.repoID
	}
	return w.Write(m)
}

// ensureFileLocked ensures the target file is open for appending, rotating per day if no fixed file name is set.
func (w *Writer) ensureFileLocked(t time.Time) (*os.File, error) {
	dateStr := t.Format("2006-01-02")
	targetName := w.fixedFile
	if targetName == "" {
		targetName = dateStr + ".jsonl"
	}

	if w.currentFile != nil {
		if w.fixedFile != "" || w.currentDate == dateStr {
			return w.currentFile, nil
		}
		// Close file for previous date
		_ = w.currentFile.Close()
		w.currentFile = nil
	}

	filePath := filepath.Join(w.dirPath, targetName)
	f, err := os.OpenFile(filePath, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0600)
	if err != nil {
		return nil, fmt.Errorf("opening metrics file %s: %w", filePath, err)
	}

	w.currentFile = f
	w.currentDate = dateStr
	return f, nil
}

// Sync flushes buffered data to underlying storage.
func (w *Writer) Sync() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.closed {
		return ErrClosed
	}

	if w.currentFile != nil {
		return w.currentFile.Sync()
	}
	return nil
}

// Close closes any open file descriptor and marks the writer as closed.
func (w *Writer) Close() error {
	w.mu.Lock()
	defer w.mu.Unlock()

	if w.closed {
		return nil
	}
	w.closed = true

	if w.currentFile != nil {
		err := w.currentFile.Close()
		w.currentFile = nil
		return err
	}
	return nil
}

// Directory returns the metrics storage directory path.
func (w *Writer) Directory() string {
	return w.dirPath
}

package metrics

import (
	"bufio"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
)

// Reader reads and aggregates telemetry records from <data-dir>/<repo-id>/metrics/*.jsonl (SPEC §10.4).
type Reader struct {
	dirPath  string
	customIO io.Reader
}

// NewReader creates a Reader for the metrics directory under <data-dir>/<repo-id>/metrics.
func NewReader(dataDir, repoID string) (*Reader, error) {
	if dataDir == "" {
		dataDir = config.DataDir()
	}
	if repoID == "" {
		return nil, fmt.Errorf("repoID cannot be empty")
	}

	metricsDir := filepath.Join(dataDir, repoID, "metrics")
	return &Reader{
		dirPath: metricsDir,
	}, nil
}

// NewReaderFromIO creates a Reader backed by an io.Reader.
func NewReaderFromIO(r io.Reader) *Reader {
	return &Reader{
		customIO: r,
	}
}

// ReadAll reads all metric records.
func (r *Reader) ReadAll() ([]GenericRecord, error) {
	return r.ReadSince(time.Time{})
}

// ReadSince reads all metric records with a timestamp >= since.
func (r *Reader) ReadSince(since time.Time) ([]GenericRecord, error) {
	if r.customIO != nil {
		return scanGenericRecords(r.customIO, since)
	}

	entries, err := os.ReadDir(r.dirPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("reading metrics directory: %w", err)
	}

	var jsonlFiles []string
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".jsonl") {
			jsonlFiles = append(jsonlFiles, entry.Name())
		}
	}
	sort.Strings(jsonlFiles)

	var all []GenericRecord
	for _, name := range jsonlFiles {
		filePath := filepath.Join(r.dirPath, name)
		f, err := os.Open(filePath)
		if err != nil {
			return nil, fmt.Errorf("opening metrics file %s: %w", filePath, err)
		}
		records, err := scanGenericRecords(f, since)
		_ = f.Close()
		if err != nil {
			return nil, fmt.Errorf("scanning %s: %w", filePath, err)
		}
		all = append(all, records...)
	}

	return all, nil
}

// ReadCaptureHealth reads all CaptureHealth records.
func (r *Reader) ReadCaptureHealth(since time.Time) ([]CaptureHealth, error) {
	var results []CaptureHealth
	err := r.scanTyped(MetricTypeCaptureHealth, since, func(data []byte) error {
		var rec CaptureHealth
		if err := json.Unmarshal(data, &rec); err != nil {
			return err
		}
		results = append(results, rec)
		return nil
	})
	return results, err
}

// ReadHookExecutions reads all HookExecution records.
func (r *Reader) ReadHookExecutions(since time.Time) ([]HookExecution, error) {
	var results []HookExecution
	err := r.scanTyped(MetricTypeHookExecution, since, func(data []byte) error {
		var rec HookExecution
		if err := json.Unmarshal(data, &rec); err != nil {
			return err
		}
		results = append(results, rec)
		return nil
	})
	return results, err
}

// ReadTickHealth reads all TickHealth records.
func (r *Reader) ReadTickHealth(since time.Time) ([]TickHealth, error) {
	var results []TickHealth
	err := r.scanTyped(MetricTypeTickHealth, since, func(data []byte) error {
		var rec TickHealth
		if err := json.Unmarshal(data, &rec); err != nil {
			return err
		}
		results = append(results, rec)
		return nil
	})
	return results, err
}

// ReadBudgetExhaustions reads all BudgetExhaustion records.
func (r *Reader) ReadBudgetExhaustions(since time.Time) ([]BudgetExhaustion, error) {
	var results []BudgetExhaustion
	err := r.scanTyped(MetricTypeBudgetExhaustion, since, func(data []byte) error {
		var rec BudgetExhaustion
		if err := json.Unmarshal(data, &rec); err != nil {
			return err
		}
		results = append(results, rec)
		return nil
	})
	return results, err
}

// ReadTranscriptMeasurements reads all TranscriptMeasurement records.
func (r *Reader) ReadTranscriptMeasurements(since time.Time) ([]TranscriptMeasurement, error) {
	var results []TranscriptMeasurement
	err := r.scanTyped(MetricTypeTranscriptMeasurement, since, func(data []byte) error {
		var rec TranscriptMeasurement
		if err := json.Unmarshal(data, &rec); err != nil {
			return err
		}
		results = append(results, rec)
		return nil
	})
	return results, err
}

func (r *Reader) scanTyped(mType MetricType, since time.Time, fn func(data []byte) error) error {
	processReader := func(rd io.Reader) error {
		scanner := bufio.NewScanner(rd)
		buf := make([]byte, 1024*1024)
		scanner.Buffer(buf, 1024*1024*10)

		for scanner.Scan() {
			line := scanner.Bytes()
			if len(line) == 0 {
				continue
			}

			var base BaseRecord
			if err := json.Unmarshal(line, &base); err != nil {
				continue
			}
			if base.Type != mType {
				continue
			}
			if !since.IsZero() && base.Timestamp.Before(since) {
				continue
			}

			if err := fn(line); err != nil {
				return err
			}
		}
		return scanner.Err()
	}

	if r.customIO != nil {
		return processReader(r.customIO)
	}

	entries, err := os.ReadDir(r.dirPath)
	if err != nil {
		if os.IsNotExist(err) {
			return nil
		}
		return err
	}

	var jsonlFiles []string
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".jsonl") {
			jsonlFiles = append(jsonlFiles, entry.Name())
		}
	}
	sort.Strings(jsonlFiles)

	for _, name := range jsonlFiles {
		filePath := filepath.Join(r.dirPath, name)
		f, err := os.Open(filePath)
		if err != nil {
			return err
		}
		err = processReader(f)
		_ = f.Close()
		if err != nil {
			return err
		}
	}

	return nil
}

func scanGenericRecords(rd io.Reader, since time.Time) ([]GenericRecord, error) {
	var results []GenericRecord
	scanner := bufio.NewScanner(rd)
	buf := make([]byte, 1024*1024)
	scanner.Buffer(buf, 1024*1024*10)

	for scanner.Scan() {
		line := scanner.Bytes()
		if len(line) == 0 {
			continue
		}

		var rec GenericRecord
		if err := json.Unmarshal(line, &rec); err != nil {
			continue
		}
		if !since.IsZero() && rec.Timestamp.Before(since) {
			continue
		}
		results = append(results, rec)
	}

	return results, scanner.Err()
}

// CaptureHealthSummary represents an aggregated overview of capture health telemetry.
type CaptureHealthSummary struct {
	TotalSessionsSeen     int            `json:"total_sessions_seen"`
	TotalSessionsCaptured int            `json:"total_sessions_captured"`
	TotalSessionsSkipped  int            `json:"total_sessions_skipped"`
	TotalSessionsMissed   int            `json:"total_sessions_missed"`
	CaptureRate           float64        `json:"capture_rate"`
	SkipReasons           map[string]int `json:"skip_reasons"`
	MissReasons           map[string]int `json:"miss_reasons"`
}

// AggregateCaptureHealth aggregates multiple CaptureHealth records.
func AggregateCaptureHealth(records []CaptureHealth) CaptureHealthSummary {
	summary := CaptureHealthSummary{
		SkipReasons: make(map[string]int),
		MissReasons: make(map[string]int),
	}

	for _, r := range records {
		summary.TotalSessionsSeen += r.SessionsSeen
		summary.TotalSessionsCaptured += r.SessionsCaptured
		summary.TotalSessionsSkipped += r.SessionsSkipped
		summary.TotalSessionsMissed += r.SessionsMissed

		for reason, count := range r.SkipReasons {
			summary.SkipReasons[reason] += count
		}
		for reason, count := range r.MissReasons {
			summary.MissReasons[reason] += count
		}
	}

	if summary.TotalSessionsSeen > 0 {
		summary.CaptureRate = float64(summary.TotalSessionsCaptured) / float64(summary.TotalSessionsSeen)
	}

	return summary
}

// HookLatencyStats records percentile distribution and cumulative metrics for hook execution.
type HookLatencyStats struct {
	EventType       string  `json:"event_type"`
	Count           int     `json:"count"`
	TotalDurationMS float64 `json:"total_duration_ms"`
	MeanDurationMS  float64 `json:"mean_duration_ms"`
	P50DurationMS   float64 `json:"p50_duration_ms"`
	P95DurationMS   float64 `json:"p95_duration_ms"`
	P99DurationMS   float64 `json:"p99_duration_ms"`
	MinDurationMS   float64 `json:"min_duration_ms"`
	MaxDurationMS   float64 `json:"max_duration_ms"`
}

// HookAggregation contains aggregated hook latency percentiles per event type and cumulative session times (SPEC §10.4).
type HookAggregation struct {
	PerEventType         map[string]HookLatencyStats `json:"per_event_type"`
	CumulativePerSession map[string]float64          `json:"cumulative_per_session"`
	MedianSessionMS      float64                     `json:"median_session_ms"`
	MeanSessionMS        float64                     `json:"mean_session_ms"`
}

// AggregateHookExecutions computes p50, p95, p99 percentiles per event type and session cumulative times.
func AggregateHookExecutions(records []HookExecution) HookAggregation {
	byType := make(map[string][]float64)
	sessionTimes := make(map[string]float64)

	for _, r := range records {
		byType[r.EventType] = append(byType[r.EventType], r.DurationMS)
		if r.SessionID != "" {
			if r.CumulativeSessionMS > 0 {
				if r.CumulativeSessionMS > sessionTimes[r.SessionID] {
					sessionTimes[r.SessionID] = r.CumulativeSessionMS
				}
			} else {
				sessionTimes[r.SessionID] += r.DurationMS
			}
		}
	}

	statsPerType := make(map[string]HookLatencyStats)
	for eventType, durations := range byType {
		if len(durations) == 0 {
			continue
		}
		sort.Float64s(durations)

		count := len(durations)
		var sum float64
		for _, d := range durations {
			sum += d
		}

		p50 := percentile(durations, 0.50)
		p95 := percentile(durations, 0.95)
		p99 := percentile(durations, 0.99)

		statsPerType[eventType] = HookLatencyStats{
			EventType:       eventType,
			Count:           count,
			TotalDurationMS: sum,
			MeanDurationMS:  sum / float64(count),
			P50DurationMS:   p50,
			P95DurationMS:   p95,
			P99DurationMS:   p99,
			MinDurationMS:   durations[0],
			MaxDurationMS:   durations[count-1],
		}
	}

	var sessionVals []float64
	var sumSession float64
	for _, total := range sessionTimes {
		sessionVals = append(sessionVals, total)
		sumSession += total
	}

	var medianSession float64
	var meanSession float64
	if len(sessionVals) > 0 {
		sort.Float64s(sessionVals)
		medianSession = percentile(sessionVals, 0.50)
		meanSession = sumSession / float64(len(sessionVals))
	}

	return HookAggregation{
		PerEventType:         statsPerType,
		CumulativePerSession: sessionTimes,
		MedianSessionMS:      medianSession,
		MeanSessionMS:        meanSession,
	}
}

// TickHealthSummary represents an aggregated overview of tick executions (SPEC §10.4).
type TickHealthSummary struct {
	TotalTicks                 int                `json:"total_ticks"`
	TotalDurationMS            float64            `json:"total_duration_ms"`
	MeanDurationMS             float64            `json:"mean_duration_ms"`
	P50DurationMS              float64            `json:"p50_duration_ms"`
	P95DurationMS              float64            `json:"p95_duration_ms"`
	BudgetExhaustionCount      int                `json:"budget_exhaustion_count"`
	TotalSkippedOverlaps       int                `json:"total_skipped_overlaps"`
	TotalSessionsCaughtBySweep int                `json:"total_sessions_caught_by_sweep"`
	MeanSpoolToDeliveryMS      float64            `json:"mean_spool_to_delivery_ms"`
	AverageBacklog             map[string]float64 `json:"average_backlog"`
}

// AggregateTickHealth computes statistical summaries for tick executions.
func AggregateTickHealth(records []TickHealth) TickHealthSummary {
	if len(records) == 0 {
		return TickHealthSummary{
			AverageBacklog: make(map[string]float64),
		}
	}

	var durations []float64
	var sumDuration float64
	var totalExhausted int
	var totalSkippedOverlaps int
	var totalCaughtBySweep int
	var sumSpoolLatency float64
	var spoolCount int
	backlogSums := make(map[string]float64)

	for _, r := range records {
		durations = append(durations, r.DurationMS)
		sumDuration += r.DurationMS
		if r.BudgetExhausted {
			totalExhausted++
		}
		totalSkippedOverlaps += r.SkippedOverlaps
		totalCaughtBySweep += r.SessionsCaughtBySweep
		if r.SpoolToDeliveryLatencyMS > 0 {
			sumSpoolLatency += r.SpoolToDeliveryLatencyMS
			spoolCount++
		}
		for kind, count := range r.JobBacklog {
			backlogSums[kind] += float64(count)
		}
	}

	sort.Float64s(durations)
	p50 := percentile(durations, 0.50)
	p95 := percentile(durations, 0.95)

	avgBacklog := make(map[string]float64)
	for kind, sum := range backlogSums {
		avgBacklog[kind] = sum / float64(len(records))
	}

	var meanSpool float64
	if spoolCount > 0 {
		meanSpool = sumSpoolLatency / float64(spoolCount)
	}

	return TickHealthSummary{
		TotalTicks:                 len(records),
		TotalDurationMS:            sumDuration,
		MeanDurationMS:             sumDuration / float64(len(records)),
		P50DurationMS:              p50,
		P95DurationMS:              p95,
		BudgetExhaustionCount:      totalExhausted,
		TotalSkippedOverlaps:       totalSkippedOverlaps,
		TotalSessionsCaughtBySweep: totalCaughtBySweep,
		MeanSpoolToDeliveryMS:      meanSpool,
		AverageBacklog:             avgBacklog,
	}
}

// BudgetSummary represents an aggregated overview of budget exhaustion records.
type BudgetSummary struct {
	TotalEvents        int            `json:"total_events"`
	ExhaustedEvents    int            `json:"exhausted_events"`
	ExhaustionByStage  map[string]int `json:"exhaustion_by_stage"`
	TotalLimitByUnit   map[string]int64 `json:"total_limit_by_unit"`
	TotalConsumedByUnit map[string]int64 `json:"total_consumed_by_unit"`
}

// AggregateBudgetExhaustion aggregates budget exhaustion records.
func AggregateBudgetExhaustion(records []BudgetExhaustion) BudgetSummary {
	summary := BudgetSummary{
		TotalEvents:         len(records),
		ExhaustionByStage:   make(map[string]int),
		TotalLimitByUnit:    make(map[string]int64),
		TotalConsumedByUnit: make(map[string]int64),
	}

	for _, r := range records {
		if r.Exhausted {
			summary.ExhaustedEvents++
			summary.ExhaustionByStage[r.Stage]++
		}
		unit := r.Unit
		if unit == "" {
			unit = "tokens"
		}
		summary.TotalLimitByUnit[unit] += r.Limit
		summary.TotalConsumedByUnit[unit] += r.Consumed
	}

	return summary
}

func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return 0
	}
	if p <= 0 {
		return sorted[0]
	}
	if p >= 1.0 {
		return sorted[len(sorted)-1]
	}

	index := p * float64(len(sorted)-1)
	lower := int(index)
	upper := lower + 1
	if upper >= len(sorted) {
		return sorted[lower]
	}
	weight := index - float64(lower)
	return sorted[lower]*(1.0-weight) + sorted[upper]*weight
}

package metrics

import (
	"bufio"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/pipeline/compact"
	"github.com/cblabs-org/repo-memory-plugin/internal/harness"
)

// TranscriptSourceType represents the source variant of a transcript.
type TranscriptSourceType string

const (
	SourceMonolithicFull TranscriptSourceType = "monolithic_full"
	SourceChunkedFull    TranscriptSourceType = "chunked_full"
	SourceCompact        TranscriptSourceType = "compact"
)

// multiReadCloser joins multiple readers and closes them all upon Close().
type multiReadCloser struct {
	io.Reader
	closers []io.Closer
}

func (m *multiReadCloser) Close() error {
	var firstErr error
	for _, c := range m.closers {
		if err := c.Close(); err != nil && firstErr == nil {
			firstErr = err
		}
	}
	return firstErr
}

// OpenTranscriptStream opens a transcript stream from a conversation directory in priority order (§6.2):
// 1. transcript_full.jsonl (complete, untruncated)
// 2. chunks/transcript_full/*.jsonl (concatenated in lexical order as a continuous byte stream)
// 3. transcript.jsonl (compact fallback)
func OpenTranscriptStream(dir string) (io.ReadCloser, TranscriptSourceType, error) {
	fullPath := filepath.Join(dir, "transcript_full.jsonl")
	if f, err := os.Open(fullPath); err == nil {
		return f, SourceMonolithicFull, nil
	}

	chunksDir := filepath.Join(dir, "chunks", "transcript_full")
	if entries, err := os.ReadDir(chunksDir); err == nil {
		var chunkFiles []string
		for _, e := range entries {
			if !e.IsDir() && strings.HasSuffix(e.Name(), ".jsonl") {
				chunkFiles = append(chunkFiles, e.Name())
			}
		}
		if len(chunkFiles) > 0 {
			sort.Strings(chunkFiles)
			var readers []io.Reader
			var closers []io.Closer
			for _, name := range chunkFiles {
				cf, err := os.Open(filepath.Join(chunksDir, name))
				if err != nil {
					for _, c := range closers {
						_ = c.Close()
					}
					return nil, "", fmt.Errorf("opening chunk %s: %w", name, err)
				}
				readers = append(readers, cf)
				closers = append(closers, cf)
			}
			return &multiReadCloser{
				Reader:  io.MultiReader(readers...),
				closers: closers,
			}, SourceChunkedFull, nil
		}
	}

	compactPath := filepath.Join(dir, "transcript.jsonl")
	if f, err := os.Open(compactPath); err == nil {
		return f, SourceCompact, nil
	}

	return nil, "", fmt.Errorf("no transcript source found in %s", dir)
}

// rawStep mirrors the raw JSONL step structure in Antigravity transcripts.
type rawStep struct {
	StepIndex       int             `json:"step_index"`
	Source          string          `json:"source"`
	Type            string          `json:"type"`
	Status          string          `json:"status"`
	CreatedAt       string          `json:"created_at"`
	Content         string          `json:"content"`
	Thinking        string          `json:"thinking"`
	ToolCalls       json.RawMessage `json:"tool_calls"`
	Media           json.RawMessage `json:"media"`
	TruncatedFields []string        `json:"truncated_fields"`
}

type toolCallItem struct {
	Name string         `json:"name"`
	Args map[string]any `json:"args"`
}

// MeasureTranscript analyzes a transcript stream, measuring raw bytes, characters, estimated tokens,
// tool traffic proportion, and compaction ratio (SPEC §4.4.1, §5.1).
func MeasureTranscript(r io.Reader) (*TranscriptMeasurement, []harness.Step, error) {
	scanner := bufio.NewScanner(r)
	buf := make([]byte, 1024*1024)
	scanner.Buffer(buf, 1024*1024*50) // up to 50MB per line

	var totalBytes int64
	var totalChars int64
	var toolChars int64
	var toolBytes int64
	var stepCount int

	var steps []harness.Step
	prevHadToolCall := false
	isSubagent := false

	compactor := compact.NewCompactor()

	for scanner.Scan() {
		line := scanner.Bytes()
		lineLen := int64(len(line)) + 1 // include newline
		totalBytes += lineLen

		trimmed := strings.TrimSpace(string(line))
		if trimmed == "" || trimmed == "CHECKPOINT" {
			continue
		}

		var rs rawStep
		if err := json.Unmarshal(line, &rs); err != nil {
			// Count raw bytes even if unmarshal fails on non-JSON line
			continue
		}

		stepCount++
		cLen := int64(len(rs.Content))
		thLen := int64(len(rs.Thinking))
		tcLen := int64(len(rs.ToolCalls))
		stepChars := cLen + thLen + tcLen
		totalChars += stepChars

		// Detect subagent indicators
		if stepCount <= 3 {
			if strings.Contains(rs.Content, "subagent_reminder") ||
				strings.Contains(rs.Content, "You are running as a subagent") ||
				strings.Contains(rs.Content, "invoked by a caller agent") ||
				strings.Contains(rs.Content, "<SYSTEM_MESSAGE>\n[Message]") {
				isSubagent = true
			}
		}

		// Detect tool traffic
		isToolStep := false
		if tcLen > 0 {
			isToolStep = true
			toolChars += tcLen
			toolBytes += tcLen
		}
		if prevHadToolCall && (rs.Type == "GENERIC" || rs.Type == "TOOL_OUTPUT" || rs.Type == "COMMAND_OUTPUT") {
			isToolStep = true
			toolChars += cLen
			toolBytes += cLen
		} else if strings.Contains(strings.ToLower(rs.Source), "tool") || rs.Type == "TOOL_OUTPUT" || rs.Type == "COMMAND_OUTPUT" {
			isToolStep = true
			toolChars += cLen
			toolBytes += cLen
		}

		prevHadToolCall = tcLen > 0

		// Normalize to harness.Step for compaction
		normStep := normalizeRawStep(rs, isToolStep)
		steps = append(steps, normStep)
	}

	if err := scanner.Err(); err != nil {
		return nil, nil, fmt.Errorf("reading transcript stream: %w", err)
	}

	// Calculate tokens (~4 chars per token standard rule of thumb)
	estTokens := totalChars / 4
	toolTokens := toolChars / 4

	var toolTrafficPct float64
	if totalChars > 0 {
		toolTrafficPct = (float64(toolChars) / float64(totalChars)) * 100.0
	}

	// Run compaction
	compacted := compactor.Compact(steps)
	var keptChars int64
	for _, s := range compacted {
		keptChars += int64(len(s.Text) + len(s.Excerpt) + len(s.Command) + len(s.Outcome))
	}
	compactedTokens := keptChars / 4

	var compactionRatio float64
	if keptChars > 0 {
		compactionRatio = float64(totalChars) / float64(keptChars)
	}

	m := &TranscriptMeasurement{
		BaseRecord: BaseRecord{
			Timestamp: time.Now().UTC(),
			Type:      MetricTypeTranscriptMeasurement,
		},
		IsSubagent:        isSubagent,
		StepCount:         stepCount,
		RawBytes:          totalBytes,
		RawChars:          totalChars,
		EstimatedTokens:   estTokens,
		ToolTrafficBytes:  toolBytes,
		ToolTrafficChars:  toolChars,
		ToolTrafficTokens: toolTokens,
		ToolTrafficPct:    toolTrafficPct,
		CompactedChars:    keptChars,
		CompactedTokens:   compactedTokens,
		CompactionRatio:   compactionRatio,
	}

	return m, steps, nil
}

// normalizeRawStep converts a rawStep into a harness.Step.
func normalizeRawStep(rs rawStep, isTool bool) harness.Step {
	step := harness.Step{
		Index: rs.StepIndex,
	}

	if len(rs.ToolCalls) > 0 {
		var calls []toolCallItem
		if err := json.Unmarshal(rs.ToolCalls, &calls); err == nil && len(calls) > 0 {
			call := calls[0]
			switch call.Name {
			case "run_command":
				step.Kind = harness.StepKindCommand
				if cmd, ok := call.Args["CommandLine"].(string); ok {
					step.Command = cmd
				}
			case "view_file":
				step.Kind = harness.StepKindRead
				if f, ok := call.Args["AbsolutePath"].(string); ok {
					step.File = f
				}
			case "replace_file_content", "write_to_file":
				step.Kind = harness.StepKindEdit
				if f, ok := call.Args["TargetFile"].(string); ok {
					step.File = f
				}
			default:
				step.Kind = harness.StepKindAgent
				step.Text = string(rs.ToolCalls)
			}
			return step
		}
	}

	if isTool {
		step.Kind = harness.StepKindCommand
		step.Excerpt = rs.Content
		return step
	}

	if rs.Type == "USER_INPUT" || rs.Source == "USER_EXPLICIT" {
		step.Kind = harness.StepKindUser
		step.Text = rs.Content
		return step
	}

	if rs.Thinking != "" {
		step.Kind = harness.StepKindReasoning
		step.Text = rs.Thinking
		return step
	}

	step.Kind = harness.StepKindAgent
	step.Text = rs.Content
	return step
}

// MeasureTranscriptDir reads and measures the transcript within a conversation directory.
func MeasureTranscriptDir(dir string) (*TranscriptMeasurement, error) {
	stream, src, err := OpenTranscriptStream(dir)
	if err != nil {
		return nil, err
	}
	defer stream.Close()

	measurement, _, err := MeasureTranscript(stream)
	if err != nil {
		return nil, err
	}

	measurement.Source = string(src)
	measurement.TranscriptID = filepath.Base(dir)

	// If parent has .system_generated/subagents, check if this dir is a subagent
	parentDir := filepath.Dir(dir)
	subagentsDir := filepath.Join(parentDir, ".system_generated", "subagents")
	if entries, err := os.ReadDir(subagentsDir); err == nil && len(entries) > 0 {
		// Parent spawned subagents
	}
	// Check if this dir itself is named in some other conversation's subagents folder
	brainDir := filepath.Dir(parentDir)
	if filepath.Base(parentDir) == "brain" || filepath.Base(brainDir) == "brain" {
		// It's in brain/<id>
	}

	// Compare with compact transcript.jsonl if present to compute truncation ratio
	compactPath := filepath.Join(dir, "transcript.jsonl")
	if fi, err := os.Stat(compactPath); err == nil && fi.Size() > 0 {
		if measurement.RawBytes > 0 {
			measurement.TruncationExpansionRatio = float64(measurement.RawBytes) / float64(fi.Size())
		}
	}

	return measurement, nil
}

// CategoryStats summarizes measurements for a transcript group.
type CategoryStats struct {
	Name            string  `json:"name"`
	Count           int     `json:"count"`
	MedianTokens    int64   `json:"median_tokens"`
	MeanTokens      int64   `json:"mean_tokens"`
	ToolTrafficPct  float64 `json:"tool_traffic_pct"`
	CompactionRatio float64 `json:"compaction_ratio"`
	MedianRawBytes  int64   `json:"median_raw_bytes"`
	MeanRawBytes    int64   `json:"mean_raw_bytes"`
}

// SizeReport captures transcript size measurements and compaction telemetry across conversations (§4.4.1).
type SizeReport struct {
	TotalTranscripts int                      `json:"total_transcripts"`
	TopLevel         CategoryStats            `json:"top_level"`
	Subagent         CategoryStats            `json:"subagent"`
	Combined         CategoryStats            `json:"combined"`
	Measurements     []*TranscriptMeasurement `json:"measurements,omitempty"`
}

// MeasureDirectories measures transcripts in the specified conversation directories and builds a SizeReport.
func MeasureDirectories(dirs []string) (*SizeReport, error) {
	var topLevel []*TranscriptMeasurement
	var subagents []*TranscriptMeasurement
	var all []*TranscriptMeasurement

	for _, d := range dirs {
		m, err := MeasureTranscriptDir(d)
		if err != nil {
			// Skip directories without transcripts
			continue
		}
		all = append(all, m)
		if m.IsSubagent {
			subagents = append(subagents, m)
		} else {
			topLevel = append(topLevel, m)
		}
	}

	if len(all) == 0 {
		return nil, errors.New("no valid transcripts found to measure")
	}

	report := &SizeReport{
		TotalTranscripts: len(all),
		TopLevel:         summarizeGroup("Antigravity top-level (re-measured)", topLevel),
		Subagent:         summarizeGroup("Antigravity subagent (re-measured)", subagents),
		Combined:         summarizeGroup("Combined", all),
		Measurements:     all,
	}

	return report, nil
}

func summarizeGroup(name string, list []*TranscriptMeasurement) CategoryStats {
	if len(list) == 0 {
		return CategoryStats{Name: name}
	}

	var tokensList []int64
	var rawBytesList []int64
	var sumTokens int64
	var sumBytes int64
	var sumToolTrafficPct float64
	var sumCompactionRatio float64

	for _, m := range list {
		tokensList = append(tokensList, m.EstimatedTokens)
		rawBytesList = append(rawBytesList, m.RawBytes)
		sumTokens += m.EstimatedTokens
		sumBytes += m.RawBytes
		sumToolTrafficPct += m.ToolTrafficPct
		if m.CompactionRatio > 0 {
			sumCompactionRatio += m.CompactionRatio
		}
	}

	sort.Slice(tokensList, func(i, j int) bool { return tokensList[i] < tokensList[j] })
	sort.Slice(rawBytesList, func(i, j int) bool { return rawBytesList[i] < rawBytesList[j] })

	n := int64(len(list))
	medianTokens := tokensList[len(tokensList)/2]
	medianBytes := rawBytesList[len(rawBytesList)/2]

	return CategoryStats{
		Name:            name,
		Count:           len(list),
		MedianTokens:    medianTokens,
		MeanTokens:      sumTokens / n,
		ToolTrafficPct:  sumToolTrafficPct / float64(n),
		CompactionRatio: sumCompactionRatio / float64(n),
		MedianRawBytes:  medianBytes,
		MeanRawBytes:    sumBytes / n,
	}
}

// FormatSection441Table formats a SizeReport into the markdown table specified in SPEC §4.4.1.
func FormatSection441Table(report *SizeReport) string {
	var sb strings.Builder
	sb.WriteString("| Transcripts | Count | Median | Mean | Tool traffic | Compaction Ratio |\n")
	sb.WriteString("|---|---|---|---|---|---|\n")

	writeRow := func(c CategoryStats) {
		if c.Count == 0 {
			return
		}
		sb.WriteString(fmt.Sprintf("| %s | %d | %dk tokens | %dk tokens | %.0f%% | %.1fx |\n",
			c.Name,
			c.Count,
			c.MedianTokens/1000,
			c.MeanTokens/1000,
			c.ToolTrafficPct,
			c.CompactionRatio,
		))
	}

	writeRow(report.TopLevel)
	writeRow(report.Subagent)
	writeRow(report.Combined)

	return sb.String()
}

package metrics_test

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/metrics"
)

func TestWriter_InMemory(t *testing.T) {
	var buf bytes.Buffer
	writer := metrics.NewWriterFromIO(&buf)

	health := metrics.NewCaptureHealth("test-repo")
	health.AddSeen(10)
	health.AddCaptured(8)
	health.AddSkipped(1, "recursion_guard")
	health.AddMissed(1, "transcript_expired")

	if err := writer.WriteCaptureHealth(health); err != nil {
		t.Fatalf("failed to write capture health: %v", err)
	}

	hook := metrics.NewHookExecution("test-repo", "sess-1", "stop", 25*time.Millisecond)
	if err := writer.WriteHookExecution(hook); err != nil {
		t.Fatalf("failed to write hook execution: %v", err)
	}

	tick := metrics.NewTickHealth("test-repo", 150*time.Millisecond)
	tick.JobBacklog["sweep"] = 2
	if err := writer.WriteTickHealth(tick); err != nil {
		t.Fatalf("failed to write tick health: %v", err)
	}

	budget := metrics.NewBudgetExhaustion("test-repo", "housekeeping", 100000, 105000, "tokens", "daily cap reached")
	if err := writer.WriteBudgetExhaustion(budget); err != nil {
		t.Fatalf("failed to write budget exhaustion: %v", err)
	}

	meas := metrics.TranscriptMeasurement{
		TranscriptID:    "tr-1",
		EstimatedTokens: 52000,
		ToolTrafficPct:  86.5,
		CompactionRatio: 4.2,
	}
	if err := writer.WriteTranscriptMeasurement(meas); err != nil {
		t.Fatalf("failed to write transcript measurement: %v", err)
	}

	lines := bytes.Split(bytes.TrimSpace(buf.Bytes()), []byte("\n"))
	if len(lines) != 5 {
		t.Fatalf("expected 5 JSONL lines, got %d", len(lines))
	}

	// Verify each line is valid JSON with proper type
	expectedTypes := []metrics.MetricType{
		metrics.MetricTypeCaptureHealth,
		metrics.MetricTypeHookExecution,
		metrics.MetricTypeTickHealth,
		metrics.MetricTypeBudgetExhaustion,
		metrics.MetricTypeTranscriptMeasurement,
	}

	for i, line := range lines {
		var rec metrics.GenericRecord
		if err := json.Unmarshal(line, &rec); err != nil {
			t.Fatalf("line %d is not valid JSON: %v", i, err)
		}
		if rec.Type != expectedTypes[i] {
			t.Errorf("line %d: expected type %s, got %s", i, expectedTypes[i], rec.Type)
		}
	}
}

func TestWriter_FileBackedAndRotation(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "metrics-test-*")
	if err != nil {
		t.Fatalf("failed to create temp dir: %v", err)
	}
	defer os.RemoveAll(tempDir)

	repoID := "repo-xyz"
	writer, err := metrics.NewWriter(tempDir, repoID, metrics.WithSyncOnWrite(true))
	if err != nil {
		t.Fatalf("failed to create writer: %v", err)
	}

	m := metrics.NewCaptureHealth(repoID)
	m.AddSeen(5)
	m.AddCaptured(5)
	if err := writer.WriteCaptureHealth(m); err != nil {
		t.Fatalf("write failed: %v", err)
	}

	if err := writer.Sync(); err != nil {
		t.Fatalf("sync failed: %v", err)
	}
	if err := writer.Close(); err != nil {
		t.Fatalf("close failed: %v", err)
	}

	// Verify file was created in metrics directory with YYYY-MM-DD.jsonl
	metricsDir := filepath.Join(tempDir, repoID, "metrics")
	today := time.Now().UTC().Format("2006-01-02") + ".jsonl"
	expectedPath := filepath.Join(metricsDir, today)

	data, err := os.ReadFile(expectedPath)
	if err != nil {
		t.Fatalf("expected metrics file at %s: %v", expectedPath, err)
	}
	if len(data) == 0 {
		t.Error("expected non-empty metrics file")
	}

	// Reader verification
	reader, err := metrics.NewReader(tempDir, repoID)
	if err != nil {
		t.Fatalf("failed to create reader: %v", err)
	}
	records, err := reader.ReadAll()
	if err != nil {
		t.Fatalf("failed to read all records: %v", err)
	}
	if len(records) != 1 {
		t.Fatalf("expected 1 record, got %d", len(records))
	}
	if records[0].Type != metrics.MetricTypeCaptureHealth {
		t.Errorf("expected type %s, got %s", metrics.MetricTypeCaptureHealth, records[0].Type)
	}
}

